html:
{%- set c = get_tax_invoice_context(doc) -%}
{%- set h = c.seller -%}
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value or 0, currency=doc.currency) }}{%- endmacro -%}
{%- macro row(en, ar, value) -%}<tr><td class="lbl">{{ en }}</td><td><b>{{ value or "-" }}</b></td><td class="lbl-ar">{{ ar }}</td></tr>{%- endmacro -%}
<style>
.bl { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #1d1d1d; }
.bl table { width: 100%; border-collapse: collapse; }
.bl .ar { direction: rtl; text-align: right; font-family: "Noto Naskh Arabic", "Noto Sans Arabic", Tahoma, "DejaVu Sans", Arial, sans-serif; }
.bl .hdr td { vertical-align: top; padding-bottom: 8px; border-bottom: 3px solid #0b3d6e; }
.bl .hdr-en, .bl .hdr-ar { width: 40%; line-height: 1.45; }
.bl .hdr-logo { width: 20%; text-align: center; vertical-align: middle !important; }
.bl .hdr-logo img { max-height: 70px; max-width: 150px; }
.bl .logo-ph { display: inline-block; width: 110px; height: 60px; line-height: 60px; border: 1px dashed #999; color: #999; font-size: 13px; letter-spacing: 2px; }
.bl .co-name { font-size: 15px; font-weight: bold; color: #0b3d6e; margin-bottom: 3px; }
.bl .title { margin: 10px 0; }
.bl .title td { background: #0b3d6e; color: #fff; padding: 6px 10px; font-size: 15px; font-weight: bold; }
.bl .box { border: 1px solid #c8c8c8; }
.bl .box th { background: #eef2f7; color: #0b3d6e; text-align: left; padding: 4px 6px; font-size: 11px; border-bottom: 1px solid #c8c8c8; }
.bl .box td { padding: 3px 6px; vertical-align: top; border-bottom: 1px solid #eee; }
.bl .lbl { color: #555; white-space: nowrap; width: 1%; }
.bl .lbl-ar { color: #555; white-space: nowrap; width: 1%; direction: rtl; text-align: right; font-family: "Noto Naskh Arabic", "Noto Sans Arabic", Tahoma, "DejaVu Sans", Arial, sans-serif; }
.bl .lines th { background: #eef2f7; color: #0b3d6e; border: 1px solid #c8c8c8; padding: 4px; font-size: 10px; text-align: center; }
.bl .lines td { border: 1px solid #ddd; padding: 4px; vertical-align: top; }
.bl .num { text-align: right; white-space: nowrap; }
.bl .ctr { text-align: center; }
.bl .muted { color: #777; font-size: 10px; }
.bl .gap { height: 7px; }
.bl .box th .bh { border: 0; padding: 4px 6px; font-weight: bold; color: #0b3d6e; white-space: nowrap; }
.bl .totals td { padding: 4px 6px; border: 1px solid #ddd; }
.bl .totals .grand td { font-weight: bold; background: #0b3d6e; color: #fff; }
.bl .ship td { width: 33%; padding: 3px 6px; vertical-align: top; border-bottom: 1px solid #eee; }
.bl .ship .k { color: #555; font-size: 10px; }
.bl .ship .k .ar { float: right; }
.bl .ctrs { font-size: 10px; line-height: 1.45; }
.bl .ctrs .cn { white-space: nowrap; }
.bl .lines th .ar { font-size: 9px; white-space: nowrap; }
.bl .ship td[colspan] { width: auto; }
.bl .totals td { white-space: nowrap; }
/* Frappe's print CSS pads every cell 6px !important; these paddings must win,
   or the shipment box pushes totals, bank and QR to a second page. */
.bl .box td, .bl .ship td, .bl .totals td { padding: 3px 6px !important; }
.bl .box th, .bl .lines th { padding: 3px 4px !important; }
.bl .lines td { padding: 3px 4px !important; }
.bl .box th .bh { padding: 3px 6px !important; }
</style>
<div class="bl">
{#- The company Letter Head (logo, names, CR, VAT); the built header only when there is none. -#}
{%- if letter_head and not no_letterhead %}<div class="lh-top" style="margin-bottom:8px;">{{ letter_head }}</div>
{%- else %}
<table class="hdr"><tr>
	<td class="hdr-en">
		<div class="co-name">{{ h.name }}</div>
		{%- for line in h.address %}<div>{{ line }}</div>{% endfor %}
		<div>VAT No.: <b>{{ h.tax_id or "-" }}</b></div>
		<div>C.R. No.: <b>{{ h.cr or "-" }}</b></div>
	</td>
	<td class="hdr-logo">
		{%- if h.logo %}<img src="{{ h.logo }}">{% else %}<div class="logo-ph">LOGO</div>{% endif %}
	</td>
	<td class="hdr-ar ar">
		<div class="co-name">{% if h.name_ar %}{{ h.name_ar }}{% else %}<span dir="ltr">{{ h.name }}</span>{% endif %}</div>
		{%- for line in h.address_ar %}<div>{{ line }}</div>{% endfor %}
		<div>الرقم الضريبي: <b>{{ h.tax_id or "-" }}</b></div>
		<div>السجل التجاري: <b>{{ h.cr or "-" }}</b></div>
	</td>
</tr></table>
{%- endif %}

<table class="title"><tr>
	<td>{{ c.title | upper }}</td>
	<td class="ar">{{ c.title_ar }}</td>
</tr></table>

<table><tr>
<td style="width:48%;vertical-align:top;">
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Invoice Details</td><td class="bh ar">تفاصيل الفاتورة</td></tr></table></th></tr>
		{{ row("Invoice No.", "رقم الفاتورة", doc.name) }}
		{{ row("Invoice Date", "تاريخ الفاتورة", frappe.utils.formatdate(doc.posting_date)) }}
		{{ row("Due Date", "تاريخ الاستحقاق", frappe.utils.formatdate(doc.due_date) if doc.due_date else "") }}
		{{ row("Job No.", "رقم العملية", c.job_no) }}
		{{ row("BL / AWB No.", "رقم البوليصة", c.bl_awb) }}
		{%- if c.hbl %}{{ row("HBL / HAWB No.", "رقم البوليصة الفرعية", c.hbl) }}{% endif %}
		{%- if doc.return_against %}{{ row("Against Invoice", "مقابل الفاتورة", doc.return_against) }}{% endif %}
	</table>
</td>
<td style="width:2%;"></td>
<td style="width:50%;vertical-align:top;">
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Buyer</td><td class="bh ar">المشتري</td></tr></table></th></tr>
		{{ row("Name", "الاسم", c.buyer.name) }}
		{%- if c.buyer.name_ar %}<tr><td class="lbl"></td><td class="ar" colspan="2"><b>{{ c.buyer.name_ar }}</b></td></tr>{% endif %}
		{{ row("VAT No.", "الرقم الضريبي", c.buyer.tax_id) }}
		{{ row("C.R. No.", "السجل التجاري", c.buyer.cr) }}
		<tr><td class="lbl">Address</td><td>{{ c.buyer.address | join(", ") or "-" }}</td><td class="lbl-ar">العنوان</td></tr>
	</table>
</td>
</tr></table>
<div class="gap"></div>

{#- Shipment (ONE Freight, 5 and 9 Nov): vessel / voyage, ports and containers.
    Containers flow on a few lines; a long list prints counts per size/type. -#}
{%- set s = c.shipment or {} -%}
{%- set ctr = s.containers or {} -%}
{%- if s.carrier or s.pol or s.pod or ctr.listed -%}
<table class="box ship">
	<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Shipment Details</td><td class="bh ar">تفاصيل الشحنة</td></tr></table></th></tr>
	<tr>
		<td><div class="k">{% if s.is_air %}Flight No.<span class="ar">رقم الرحلة</span>{% else %}Vessel / Voyage<span class="ar">السفينة / الرحلة</span>{% endif %}</div><b>{{ s.carrier or "-" }}</b></td>
		<td><div class="k">Port of Loading<span class="ar">ميناء الشحن</span></div><b>{{ s.pol or "-" }}</b></td>
		<td><div class="k">Port of Discharge<span class="ar">ميناء التفريغ</span></div><b>{{ s.pod or "-" }}</b></td>
	</tr>
	{%- if ctr.listed %}
	<tr><td colspan="3"><div class="k">Containers ({{ ctr.listed | length + ctr.more }})<span class="ar">الحاويات</span></div>
		<div class="ctrs">{% if ctr.summary %}<b>{{ ctr.summary }}</b><br>{% endif %}{% for x in ctr.listed %}<span class="cn">{{ x }}</span>{% if not loop.last %} · {% endif %}{% endfor %}{% if ctr.more %} &nbsp;… and {{ ctr.more }} more{% endif %}</div></td></tr>
	{%- endif %}
</table>
<div class="gap"></div>
{%- endif %}

<table class="lines">
	<thead><tr>
		<th style="width:4%;">#</th>
		<th>Description<br><span class="ar">الوصف</span></th>
		<th style="width:8%;">Qty<br><span class="ar">الكمية</span></th>
		<th style="width:11%;">Rate<br><span class="ar">السعر</span></th>
		<th style="width:16%;">Taxable Amount<br><span class="ar">المبلغ الخاضع للضريبة</span></th>
		<th style="width:7%;">VAT %<br><span class="ar">نسبة الضريبة</span></th>
		<th style="width:11%;">VAT<br><span class="ar">الضريبة</span></th>
		<th style="width:13%;">Total<br><span class="ar">الإجمالي</span></th>
	</tr></thead>
	<tbody>
	{%- for line in c.lines %}
	<tr>
		<td class="ctr">{{ line.idx }}</td>
		<td>{{ line.description }}{% if line.detail %}<div class="muted">{{ line.detail | striptags }}</div>{% endif %}</td>
		<td class="num">{{ line.qty }}{% if line.uom %} <span class="muted">{{ line.uom }}</span>{% endif %}</td>
		<td class="num">{{ money(line.rate) }}</td>
		<td class="num">{{ money(line.amount) }}</td>
		<td class="num">{{ line.vat_rate if line.vat_rate is not none else "-" }}</td>
		<td class="num">{{ money(line.vat_amount) if line.vat_amount is not none else "-" }}</td>
		<td class="num">{{ money(line.total) }}</td>
	</tr>
	{%- endfor %}
	</tbody>
</table>
<div class="gap"></div>

{#- Bottom: amount in words and bank details on the left, totals and the ZATCA QR on
    the right, so a usual invoice stays on one page. -#}
<table><tr>
<td style="width:55%;vertical-align:top;padding-right:10px;">
	<table class="box">
		<tr><th colspan="1" style="padding:0;"><table><tr><td class="bh">Amount in Words</td><td class="bh ar">المبلغ كتابة</td></tr></table></th></tr>
		<tr><td>{{ c.words_en }}</td></tr>
		{%- if c.words_ar %}<tr><td class="ar">{{ c.words_ar }}</td></tr>{% endif %}
	</table>
	<div class="gap"></div>
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Bank Details</td><td class="bh ar">بيانات البنك</td></tr></table></th></tr>
		{%- if c.bank %}
		{{ row("Bank", "البنك", c.bank.bank) }}
		{%- set acct = c.bank.account_name or h.name -%}
		{{ row("Account Name", "اسم الحساب", (acct ~ " / " ~ h.name_ar) if (acct == h.name and h.name_ar) else acct) }}
		{%- if c.bank.account_no %}{{ row("Account No.", "رقم الحساب", c.bank.account_no) }}{% endif %}
		{{ row("IBAN", "الآيبان", c.bank.iban) }}
		{%- if c.bank.swift %}{{ row("SWIFT", "سويفت", c.bank.swift) }}{% endif %}
		{%- else %}
		<tr><td class="muted" colspan="3">-</td></tr>
		{%- endif %}
	</table>
</td>
<td style="width:45%;vertical-align:top;">
	<table class="totals">
		<tr><td>Total (excl. VAT)</td><td class="ar">الإجمالي قبل الضريبة</td><td class="num">{{ money(doc.total) }}</td></tr>
		{%- if c.discount %}
		<tr><td>Discount</td><td class="ar">الخصم</td><td class="num">- {{ money(c.discount) }}</td></tr>
		<tr><td>Net Total</td><td class="ar">الصافي</td><td class="num">{{ money(c.net_total) }}</td></tr>
		{%- endif %}
		<tr><td>Total VAT</td><td class="ar">إجمالي الضريبة</td><td class="num">{{ money(c.total_vat) }}</td></tr>
		<tr class="grand"><td>Grand Total</td><td class="ar">الإجمالي شامل الضريبة</td><td class="num">{{ money(c.grand_total) }}</td></tr>
	</table>
	{#- The company stamp beside the ZATCA QR (ONE Freight, 9 Nov). -#}
	<table style="margin-top:8px;"><tr>
		<td style="text-align:center;vertical-align:bottom;">
			{%- if h.stamp %}<img src="{{ h.stamp }}" style="max-width:140px;max-height:85px;"><br>{% endif %}
			<div class="muted">This is a computer-generated tax invoice.</div>
			<div class="muted ar" style="text-align:center;">هذه فاتورة ضريبية صادرة إلكترونياً.</div>
		</td>
		{%- if c.qr %}
		<td style="width:110px;text-align:right;vertical-align:middle;"><img src="{{ c.qr }}" style="width:105px;height:105px;"></td>
		{%- endif %}
	</tr></table>
</td>
</tr></table>
{%- if doc.terms %}
<div class="gap"></div>
<div class="muted">{{ doc.terms }}</div>
{%- endif %}

</div>

{#- Letter Head footer (address, website, email): repeated at the foot of each PDF page. -#}
{%- if footer and not no_letterhead %}
{#- `.print-format` margin is read as the PDF bottom margin; `body .print-format` keeps it off the page body.
    `letter-head-footer` cancels the 15mm top padding of Frappe's PDF footer page. -#}
<style>.print-format { margin-bottom: 18mm; } body .print-format { margin-bottom: 0; }</style>
<div id="footer-html" class="visible-pdf"><div class="letter-head-footer">{{ footer }}</div></div>
{%- endif %}
